mapper.select:
select count(*)
	from tbl_report
		where reporter_seq = #{reporterSeq}
			and target_type = #{targetType}
			and target_seq = #{targetSeq}
			and status in ('RECEIVED', 'REVIEWING')

select r.report_seq, r.reporter_seq, r.target_type, r.target_seq, r.reason_type, r.status, to_char(r.regdate, 'YYYY-MM-DD HH24:MI') as regdate, m.id as reporter_id from tbl_report r join tbl_member m on r.reporter_seq = m.member_seq
r.status = #{status}
order by r.report_seq desc

select customer_seq
	from tbl_request
		where request_seq = #{targetSeq}

mapper.update:
update tbl_report
	set status = 'REVIEWING',
		admin_seq = #{adminSeq}
	where report_seq = #{reportSeq}

update tbl_expert_profile
	set hidden = #{hidden}
		where expert_seq = #{targetSeq}

update tbl_request
	set hidden = #{hidden}
		where request_seq = #{targetSeq}
